),
live as (select p.oid::regprocedure::text as sig, md5(p.prosrc) raw,
   md5(btrim(regexp_replace(regexp_replace(p.prosrc, '^[ \t]*--[^\n]*(\n|$)', '', 'gn'), '\s+', ' ', 'g'))) norm,
   md5(concat_ws('|', pg_get_function_result(p.oid), p.prosecdef, p.provolatile, coalesce(p.proconfig::text,''), l.lanname)) hdr
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
 where n.nspname='public'
   and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
cmp as (select coalesce(e.sig, l.sig) sig, split_part(coalesce(e.sig, l.sig), '(', 1) in ('acct_post_entry','acct_require_admin','acct_void_entry','approval_rules_list','approval_rules_save','approvals_list','attendance_day','attendance_me','attendance_month','attendance_record_add','attendance_record_guard','attendance_record_json','attendance_record_void','audit_module','board_project_save','can_keep_books','can_manage_attendance','company_document_archive','company_document_save','company_get','company_profile_save','dashboard_overview','lead_convert','notify_from_audit','procurement_deliveries_to_stock','procurement_project_choices','project_duplicate_guard','project_duplicates','site_visit_from_event','stage_approval_guard','stage_needs_approval','stage_prev','stage_review','stage_submission_guard','stage_submit','stock_category_guess') as in_18_22,
  case when l.sig is null then 'MISSING LIVE' when e.sig is null then 'EXTRA LIVE (not in migrations)'
       when e.hdr <> l.hdr then 'DIFFERENT HEADER (return/security/volatility/search_path)'
       when e.raw = l.raw then 'exact' when e.norm = l.norm then 'same_code' else 'DIFFERENT BODY' end status
  from expected e full join live l on l.sig = e.sig)
select sig, in_18_22, status from cmp where status not in ('exact','same_code')
union all select 'ALL MATCH: ' || count(*) filter (where status='exact') || ' exact, ' || count(*) filter (where status='same_code') || ' same code; ' || count(*) filter (where in_18_22) || ' from 18-22', null, 'summary'
from cmp having bool_and(status in ('exact','same_code'))
order by 3, 1;
